{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — A Sound Bath Series</title>
  <meta name="description" content="Tender, sensory sound baths in {{CITY}}, {{STATE}} — an intimate series to restore calm and expand presence.">
  <link rel="stylesheet" href="/assets/css/styles.css">
  <script defer src="/assets/js/main.js"></script>
</head>
<body class="layout-earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="primary-nav" aria-label="Main navigation">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/about.html">About</a>
        <a href="/contact.html">Connect</a>
      </nav>
      <div class="actions">
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="menu-toggle" aria-label="Open menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="pattern"></div>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="title">Evening sound baths for deep release</h1>
          <p class="lede">Slow waves of crystal bowls and warm tone invite a soft fall into presence. Join a small series to replenish the nervous system, held in the quiet warmth of {{VENUE_NAME}}.</p>
          <ul class="meta">
            <li><strong>Series:</strong> Weekly sound bath — events series</li>
            <li><strong>Next:</strong> <time datetime="{{NEXT_EVENT_DATE}}">{{NEXT_EVENT_DATE}}</time></li>
            <li><strong>Facilitator:</strong> {{FACILITATOR_NAME}}</li>
          </ul>
          <p><a class="primary-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        </div>
        <div class="hero-aside">
          <div class="card">
            <h3>What to know</h3>
            <p class="small">Arrive 15 min early. We provide mats, bolsters and blankets; bring a small item for personal comfort if you wish.</p>
            <dl>
              <dt>Duration</dt>
              <dd>75 minutes (settle / sound / rest)</dd>
              <dt>Instruments</dt>
              <dd>Crystal bowls, chimes, a gentle gong</dd>
            </dl>
          </div>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC (who it's for & contraindications) -->
    <section class="diagnostic wrap">
      <header>
        <h2>A space for nervous system care</h2>
        <p class="sub">This series is curated for people seeking gentle somatic reset and a richer interior presence.</p>
      </header>
      <div class="grid">
        <div>
          <h3>Is this right for you?</h3>
          <ul>
            <li>You notice chronic tension or disrupted sleep</li>
            <li>You want a sensitive, restorative group container</li>
            <li>You prefer low lights and slow soundscapes</li>
          </ul>
        </div>
        <div>
          <h3>Contraindications</h3>
          <p class="muted">If you are pregnant, have epilepsy, recent head injury, or are undergoing intensive psychiatric treatment please consult your physician before attending. Sound can be activating; contact us at {{EMAIL}} for specific concerns.</p>
        </div>
      </div>
    </section>

    <!-- PLAN (flow) -->
    <section class="plan wrap">
      <header>
        <h2>Evening flow</h2>
        <p class="sub">A gentle arc that invites someone in and eases them out, held with intention.</p>
      </header>
      <ol class="flow">
        <li>
          <strong>Arrive & settle (15m)</strong>
          <p class="small">Quiet check-in, choose a spot, soft breathwork to arrive in the body.</p>
        </li>
        <li>
          <strong>Main soundscape (45m)</strong>
          <p class="small">Layered instruments — crystal bowls, tuning forks, and a soft monochord — guide resonant frequencies through the room.</p>
        </li>
        <li>
          <strong>Integration & gentle close (15m)</strong>
          <p class="small">Return to eyes-open slowly, a short guided reflection and tea to ground.</p>
        </li>
      </ol>
    </section>

    <!-- MICRO_HABITS -->
    <section class="micro-habits wrap">
      <header>
        <h2>Tiny practices between gatherings</h2>
        <p class="sub">Short, daily rituals to carry the reset forward.</p>
      </header>
      <ul class="habits">
        <li>
          <h4>Sound pause — 3 minutes</h4>
          <p class="small">Play a single singing bowl tone on exhale, listen until silence.</p>
        </li>
        <li>
          <h4>Feet-on-earth</h4>
          <p class="small">Stand barefoot for 60 seconds focusing on contact and breath.</p>
        </li>
        <li>
          <h4>Breath count</h4>
          <p class="small">Inhale 4, exhale 6 for six rounds before sleep.</p>
        </li>
      </ul>
    </section>

    <!-- PRICING -->
    <section class="pricing wrap" id="pricing">
      <header>
        <h2>Offer & pricing</h2>
        <p class="sub">Small series pricing for sustained benefit.</p>
      </header>
      <div class="plans">
        <div class="plan-card">
          <h3>Drop-in</h3>
          <p class="price">$35</p>
          <p class="small">Single session — perfect for a night of rest.</p>
          <a class="btn" href="/book.html?type=dropin">Book a seat</a>
        </div>
        <div class="plan-card featured">
          <h3>4-week series</h3>
          <p class="price">$120</p>
          <p class="small">Weekly container — best for nervous system recalibration.</p>
          <a class="btn btn-primary" href="/book.html?type=series">Reserve series</a>
        </div>
        <div class="plan-card">
          <h3>Concession</h3>
          <p class="price">Sliding scale</p>
          <p class="small">Limited spots — apply via email at {{EMAIL}}</p>
          <a class="btn" href="/contact.html">Request</a>
        </div>
      </div>
      <p class="disclaimer muted">All sessions are complementary to medical care. If you have implants or significant hearing concerns, consult your provider.</p>
    </section>

    <!-- CTA -->
    <section class="cta wrap">
      <div class="cta-inner">
        <h2>Ready to come home to your breath?</h2>
        <p class="sub">Reserve a place in the next gathering or inquire about private sessions.</p>
        <p><a class="primary-cta large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        <p class="contact-line">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="foot-brand">{{BUSINESS_NAME}} — {{TAGLINE}}</div>
      <nav class="foot-nav">
        <a href="/privacy.html">Privacy</a>
        <a href="/faq.html">FAQ</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <div class="social">&copy; <span id="year"></span> {{BUSINESS_NAME}}</div>
    </div>
  </footer>
</body>
</html>"} 
